begin;create extension if not exists pgtap with schema extensions;set local search_path=public,extensions;select no_plan();
insert into auth.users(id,email,raw_user_meta_data) values('ac000000-0000-4000-8000-000000000001','care-admin@example.test','{"first_name":"Care","last_name":"Admin"}'),('ac000000-0000-4000-8000-000000000002','care-staff@example.test','{"first_name":"Care","last_name":"Staff"}');
insert into public.user_roles(user_id,role) values('ac000000-0000-4000-8000-000000000001','ADMIN') on conflict do nothing;
create temp table care_fixture(kind text primary key,id uuid);grant all on care_fixture to authenticated,service_role;
select ok(not has_table_privilege('authenticated','public.care_reminder_jobs','UPDATE'),'Browser cannot mark jobs sent');
select ok(not has_table_privilege('authenticated','public.care_plan_revisions','DELETE'),'Due history cannot be deleted');
set local role authenticated;select set_config('request.jwt.claims','{"sub":"ac000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
insert into care_fixture select 'client',id from public.save_client(auth.uid(),null,null,'Synthetic','Care',null,null,'EMAIL',null,null);
insert into care_fixture select 'pet',id from public.save_patient(null,(select id from care_fixture where kind='client'),null,'Juniper {{due_date}}','Dog',null,null,'unknown',null,'unknown','unknown',null,null,null);
insert into care_fixture select 'other',id from public.save_patient(null,(select id from care_fixture where kind='client'),null,'Other','Cat',null,null,'unknown',null,'unknown','unknown',null,null,null);
insert into care_fixture select 'product',id from public.save_catalog_product(null,null,'Synthetic exact vaccine','vaccine','','dose',100,true);
insert into care_fixture select 'otherproduct',id from public.save_catalog_product(null,null,'Different vaccine','vaccine','','dose',100,true);
select lives_ok($$select public.save_vaccine_due_template('ac100000-0000-4000-8000-000000000001',null,'synthetic-group','Synthetic reviewed group',array[(select id from care_fixture where kind='product')],30,true,'Dr synthetic review; exact product mapping')$$,'Explicit product group and interval reviewed');
select lives_ok($$select public.save_vaccine_due_template('ac100000-0000-4000-8000-000000000001',null,'synthetic-group','Synthetic reviewed group',array[(select id from care_fixture where kind='product')],30,true,'Dr synthetic review; exact product mapping')$$,'Template replay idempotent');
select is((select count(*) from public.care_plan_revisions),1::bigint,'No duplicate reviewed template');
select throws_ok($$select public.save_vaccine_due_template(gen_random_uuid(),null,'other','Other',array[(select id from care_fixture where kind='product')],0,true,'Reviewed')$$,'23514',null,'No zero medical interval');
create function pg_temp.care_plan(p_id uuid,p_version integer,p_due date default '2026-01-31',p_status text default 'current',p_enabled boolean default true,p_override text default '',p_template_version integer default 1) returns public.patient_vaccine_due_plans language sql as $$select public.save_patient_vaccine_due_plan(p_id,(select id from care_fixture where kind='pet'),p_version,'ac100000-0000-4000-8000-000000000001',p_template_version,(select id from care_fixture where kind='product'),null,'2026-01-01','Prior paper record reviewed',30,p_due,p_status,p_enabled,p_override,'Reviewed patient due plan')$$;
select lives_ok($$select pg_temp.care_plan('ac200000-0000-4000-8000-000000000001',null)$$,'Create current canonical due plan');
select lives_ok($$select pg_temp.care_plan('ac200000-0000-4000-8000-000000000001',null)$$,'Plan replay idempotent');
select throws_ok($$select pg_temp.care_plan(gen_random_uuid(),null)$$,'23505',null,'Duplicate active antigen group rejected');
select throws_ok($$select pg_temp.care_plan('ac200000-0000-4000-8000-000000000001',0,'2026-02-01')$$,'40001',null,'Stale plan edit rejected');
select throws_ok($$select pg_temp.care_plan('ac200000-0000-4000-8000-000000000001',1,'2026-02-01')$$,'23514',null,'Due override requires reason');
select throws_ok($$select public.save_patient_vaccine_due_plan('ac200000-0000-4000-8000-000000000001',(select id from care_fixture where kind='other'),1,'ac100000-0000-4000-8000-000000000001',1,(select id from care_fixture where kind='product'),null,'2026-01-01','Source',30,'2026-01-31','current',true,'','Review')$$,'42501',null,'Cross patient due write rejected');
select throws_ok($$select public.save_patient_vaccine_due_plan(gen_random_uuid(),(select id from care_fixture where kind='other'),null,'ac100000-0000-4000-8000-000000000001',1,(select id from care_fixture where kind='otherproduct'),null,'2026-01-01','Source',30,'2026-01-31','current',true,'','Review')$$,'23514',null,'Unmapped product is not treated as equivalent');
select lives_ok($$select public.save_care_message_template('ac300000-0000-4000-8000-000000000001',null,'Reviewed email','email',7,'{{patient_name}}: {{care_name}} due {{due_date}}',true,'Reviewed plain text wording')$$,'Create reviewed reminder wording');
select throws_ok($$select public.save_care_message_template(gen_random_uuid(),null,'Bad tokens','sms',0,'{{unknown}}',true,'Reviewed')$$,'23514',null,'Unsupported rendering tokens rejected');
select throws_ok($$select public.enqueue_care_reminder(gen_random_uuid(),'vaccine','ac200000-0000-4000-8000-000000000001',1,'ac300000-0000-4000-8000-000000000001',1)$$,'42501',null,'Browser cannot enqueue service jobs');
set local role service_role;select set_config('request.jwt.claims','{"role":"service_role"}',true);
select lives_ok($$select public.enqueue_care_reminder('ac400000-0000-4000-8000-000000000001','vaccine','ac200000-0000-4000-8000-000000000001',1,'ac300000-0000-4000-8000-000000000001',1)$$,'Service creates unsent durable job');
select is((select id from public.enqueue_care_reminder(gen_random_uuid(),'vaccine','ac200000-0000-4000-8000-000000000001',1,'ac300000-0000-4000-8000-000000000001',1)),'ac400000-0000-4000-8000-000000000001'::uuid,'Different request UUID cannot duplicate same source/template version');
select throws_ok($$select public.enqueue_care_reminder(gen_random_uuid(),'vaccine','ac200000-0000-4000-8000-000000000001',0,'ac300000-0000-4000-8000-000000000001',1)$$,'40001',null,'Stale source cannot enqueue');
set local role authenticated;select set_config('request.jwt.claims','{"sub":"ac000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select is((select rendered_body from public.care_reminder_jobs where id='ac400000-0000-4000-8000-000000000001'),'Juniper {{due_date}}: Synthetic reviewed group due 2026-01-31','Slot values are not recursively interpreted as template tokens');
select is((select scheduled_on from public.care_reminder_jobs where id='ac400000-0000-4000-8000-000000000001'),'2026-01-24'::date,'Reviewed offset calculates calendar job date');
select is((select status from public.care_reminder_jobs where id='ac400000-0000-4000-8000-000000000001'),'pending','Enqueue never claims delivery');
select lives_ok($$select public.save_vaccine_due_template('ac100000-0000-4000-8000-000000000001',1,'synthetic-group','Revised group',array[(select id from care_fixture where kind='product')],60,true,'Later review')$$,'Practice standard can change explicitly');
select is((select current_due_on from public.patient_vaccine_due_plans where id='ac200000-0000-4000-8000-000000000001'),'2026-01-31'::date,'No silent retroactive patient due changes');
select lives_ok($$select pg_temp.care_plan('ac200000-0000-4000-8000-000000000001',1,'2026-02-01','current',true,'Reviewed patient correction')$$,'Old reviewed snapshot allows explicit patient correction');
select is((select status from public.care_reminder_jobs where id='ac400000-0000-4000-8000-000000000001'),'invalidated','Due correction invalidates prior pending job');
set local role service_role;select set_config('request.jwt.claims','{"role":"service_role"}',true);
select lives_ok($$select public.enqueue_care_reminder('ac400000-0000-4000-8000-000000000002','vaccine','ac200000-0000-4000-8000-000000000001',2,'ac300000-0000-4000-8000-000000000001',1)$$,'Revised due produces new source-version job');
set local role authenticated;select set_config('request.jwt.claims','{"sub":"ac000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select lives_ok($$select pg_temp.care_plan('ac200000-0000-4000-8000-000000000001',2,'2026-02-01','current',false,'Reviewed patient correction')$$,'Patient-specific reminders can be disabled');
select is((select status from public.care_reminder_jobs where id='ac400000-0000-4000-8000-000000000002'),'invalidated','Disabled plan invalidates pending job');
set local role service_role;select set_config('request.jwt.claims','{"role":"service_role"}',true);
select throws_ok($$select public.enqueue_care_reminder(gen_random_uuid(),'vaccine','ac200000-0000-4000-8000-000000000001',3,'ac300000-0000-4000-8000-000000000001',1)$$,'40001',null,'Disabled plan cannot enqueue');
set local role authenticated;select set_config('request.jwt.claims','{"sub":"ac000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select lives_ok($$select public.save_patient_lab_order('ac500000-0000-4000-8000-000000000001',(select id from care_fixture where kind='pet'),null,'{"test_name":"Synthetic lab","status":"planned","due_date":"2026-10-01"}','')$$,'Uses existing lab due order without duplicate interval catalog');
set local role service_role;select set_config('request.jwt.claims','{"role":"service_role"}',true);
select lives_ok($$select public.enqueue_care_reminder('ac400000-0000-4000-8000-000000000003','lab','ac500000-0000-4000-8000-000000000001',1,'ac300000-0000-4000-8000-000000000001',1)$$,'Existing lab order enqueues');
set local role authenticated;select set_config('request.jwt.claims','{"sub":"ac000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select lives_ok($$select public.save_patient_lab_order('ac500000-0000-4000-8000-000000000001',(select id from care_fixture where kind='pet'),1,'{"test_name":"Synthetic lab","status":"cancelled","due_date":"2026-10-01"}','')$$,'Cancel original lab order');
select is((select status from public.care_reminder_jobs where id='ac400000-0000-4000-8000-000000000003'),'invalidated','Lab cancellation invalidates its pending job');
select lives_ok($$select pg_temp.care_plan('ac200000-0000-4000-8000-000000000001',3,'2026-02-01','retired',false,'Reviewed retirement')$$,'Plan can retire');
select throws_ok($$select pg_temp.care_plan('ac200000-0000-4000-8000-000000000001',4,'2026-02-01','current',true,'Resurrect')$$,'23514',null,'Retired history cannot be resurrected');
reset role;
insert into public.patient_treatments(id,pet_id,product_id,kind,historical,product_name,manufacturer,lot_number,quantity,dose,route,site,veterinarian,veterinarian_license,administered_at,source,request,created_by) values('ac600000-0000-4000-8000-000000000001',(select id from care_fixture where kind='pet'),(select id from care_fixture where kind='product'),'vaccine',true,'Synthetic exact vaccine','','',1,'Recorded dose','Recorded route','','Synthetic veterinarian','','2026-01-01T06:30:00Z','Synthetic paper source','{}',auth.uid());
set local role authenticated;
select throws_ok($$select public.save_patient_vaccine_due_plan(gen_random_uuid(),(select id from care_fixture where kind='pet'),null,'ac100000-0000-4000-8000-000000000001',2,(select id from care_fixture where kind='product'),'ac600000-0000-4000-8000-000000000001','2026-01-01','Linked source',60,'2026-03-02','current',true,'','Reviewed')$$,'23514',null,'Linked administration requires exact Denver calendar day');
select lives_ok($$select public.save_patient_vaccine_due_plan('ac200000-0000-4000-8000-000000000002',(select id from care_fixture where kind='pet'),null,'ac100000-0000-4000-8000-000000000001',2,(select id from care_fixture where kind='product'),'ac600000-0000-4000-8000-000000000001','2025-12-31','Linked source',60,'2026-03-01','current',true,'','Reviewed')$$,'Actual administration anchor accepted without inferring brand equivalence');
set local role service_role;select set_config('request.jwt.claims','{"role":"service_role"}',true);
select lives_ok($$select public.enqueue_care_reminder('ac400000-0000-4000-8000-000000000004','vaccine','ac200000-0000-4000-8000-000000000002',1,'ac300000-0000-4000-8000-000000000001',1)$$,'New canonical reviewed plan enqueues');
select is((select count(*) from public.list_care_reminder_candidates('2026-12-31','', '00000000-0000-0000-0000-000000000000',1)),1::bigint,'Service discovery is bounded and sees current due plans');
set local role authenticated;select set_config('request.jwt.claims','{"sub":"ac000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select lives_ok($$select public.correct_patient_treatment('ac700000-0000-4000-8000-000000000001','ac600000-0000-4000-8000-000000000001','Source entry corrected',null)$$,'Actual administration can be corrected');
select is((select status from public.patient_vaccine_due_plans where id='ac200000-0000-4000-8000-000000000002'),'proposed','Corrected administration requires new review of patient due date');
select is((select status from public.care_reminder_jobs where id='ac400000-0000-4000-8000-000000000004'),'invalidated','Correction invalidates pending reminder snapshot');
select lives_ok($$select public.save_patient_vaccine_due_plan('ac200000-0000-4000-8000-000000000002',(select id from care_fixture where kind='pet'),2,'ac100000-0000-4000-8000-000000000001',2,(select id from care_fixture where kind='product'),null,'2025-12-31','Reviewed independent historical source',60,'2026-03-01','current',true,'','Reviewed corrected plan')$$,'Review can replace corrected anchor with explicit independent provenance');
set local role service_role;select set_config('request.jwt.claims','{"role":"service_role"}',true);
select lives_ok($$select public.enqueue_care_reminder('ac400000-0000-4000-8000-000000000005','vaccine','ac200000-0000-4000-8000-000000000002',3,'ac300000-0000-4000-8000-000000000001',1)$$,'Reviewed corrected source produces new job');
set local role authenticated;select set_config('request.jwt.claims','{"sub":"ac000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select lives_ok($$select public.save_care_message_template('ac300000-0000-4000-8000-000000000001',1,'Retired email','email',7,'{{patient_name}}: {{care_name}} due {{due_date}}',false,'Retired wording after review')$$,'Wording can retire with review');
select is((select status from public.care_reminder_jobs where id='ac400000-0000-4000-8000-000000000005'),'invalidated','Retired wording invalidates pending jobs without rewriting body');
reset role;update public.pets set archived_at=now() where id=(select id from care_fixture where kind='pet');
set local role service_role;select set_config('request.jwt.claims','{"role":"service_role"}',true);
select throws_ok($$select public.enqueue_care_reminder(gen_random_uuid(),'vaccine','ac200000-0000-4000-8000-000000000002',3,'ac300000-0000-4000-8000-000000000001',2)$$,'23514',null,'Archived patient cannot enqueue');
select is((select count(*) from public.list_care_reminder_candidates('2026-12-31')),0::bigint,'Inactive patients absent from service discovery');
set local role authenticated;select set_config('request.jwt.claims','{"sub":"ac000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select throws_ok($$select pg_temp.care_plan(gen_random_uuid(),null,'2026-01-31','current',true,'Reviewed',2)$$,'23514',null,'Archived patient cannot get a new due plan');
select set_config('request.jwt.claims','{"sub":"ac000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select throws_ok($$select public.save_care_message_template(gen_random_uuid(),null,'Not approved','sms',0,'Text',true,'Note')$$,'42501',null,'Staff cannot approve practice message settings');
select * from finish();rollback;
